import java.security.MessageDigest
import java.nio.charset.StandardCharsets
import java.text.Normalizer
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64

object TokenService {
  private val SECRET = sys.env.getOrElse("HMAC_SECRET", "default-secret-key-32bytes!!!!!")
  private val ALGORITHM = "HmacSHA256"

  case class Token(userId: String, role: String, expiry: Long, signature: String)

  def createToken(userId: String, role: String, ttlSeconds: Long): Token = {
    val expiry = System.currentTimeMillis() / 1000 + ttlSeconds
    val payload = s"$userId|$role|$expiry"
    val sig = computeHmac(payload)
    Token(userId, role, expiry, sig)
  }

  def computeHmac(data: String): String = {
    val mac = Mac.getInstance(ALGORITHM)
    mac.init(new SecretKeySpec(SECRET.getBytes(StandardCharsets.UTF_8), ALGORITHM))
    Base64.getUrlEncoder.withoutPadding.encodeToString(mac.doFinal(data.getBytes(StandardCharsets.UTF_8)))
  }

  def verifyToken(token: Token): Boolean = {
    val payload = s"${token.userId}|${token.role}|${token.expiry}"
    val expectedSig = computeHmac(payload)
    val now = System.currentTimeMillis() / 1000
    if (now > token.expiry) return false
    constantTimeEquals(token.signature, expectedSig)
  }

  private def constantTimeEquals(a: String, b: String): Boolean = {
    if (a.length != b.length) return false
    var result = 0
    for (i <- 0 until a.length) {
      result |= a.charAt(i) ^ b.charAt(i)
    }
    result == 0
  }
}

object PathAuthorizer {
  private val ACL_RULES: Map[String, Set[String]] = Map(
    "/admin" -> Set("admin"),
    "/admin/users" -> Set("admin"),
    "/admin/config" -> Set("admin", "superadmin"),
    "/api/data" -> Set("admin", "user", "viewer"),
    "/api/upload" -> Set("admin", "user"),
    "/public" -> Set("admin", "user", "viewer", "anonymous")
  )

  def normalizePath(path: String): String = {
    // Decode percent-encoding
    val decoded = java.net.URLDecoder.decode(path, StandardCharsets.UTF_8.name())
    // Unicode NFC normalization
    val normalized = Normalizer.normalize(decoded, Normalizer.Form.NFC)
    // Collapse multiple slashes, remove trailing slash
    val collapsed = normalized.replaceAll("/+", "/").stripSuffix("/")
    // Resolve . and ..
    val parts = collapsed.split("/").toList
    val resolved = parts.foldLeft(List.empty[String]) { (acc, part) =>
      part match {
        case "" if acc.isEmpty => List("")
        case "" => acc
        case "." => acc
        case ".." => if (acc.length > 1) acc.dropRight(1) else acc
        case other => acc :+ other
      }
    }
    val result = resolved.mkString("/")
    if (result.isEmpty) "/" else result
  }

  def checkAccess(path: String, role: String): Boolean = {
    // First check ACL against the raw path for exact match
    val matchResult = findMatchingRule(path, role)
    if (matchResult.isDefined) return matchResult.get

    // Then normalize and check again
    val normalizedPath = normalizePath(path)
    val normalizedResult = findMatchingRule(normalizedPath, role)
    normalizedResult.getOrElse(false)
  }

  private def findMatchingRule(path: String, role: String): Option[Boolean] = {
    // Find longest prefix match
    val matchingRules = ACL_RULES.keys.filter(rule => path.startsWith(rule))
    if (matchingRules.isEmpty) return None
    val bestMatch = matchingRules.maxBy(_.length)
    Some(ACL_RULES(bestMatch).contains(role))
  }
}

object ResourceServer {
  case class Resource(id: String, path: String, content: String, owner: String)

  private var resources: Map[String, Resource] = Map(
    "secret-config" -> Resource("secret-config", "/admin/config", "database_password=hunter2", "system"),
    "user-data" -> Resource("user-data", "/api/data", "user records...", "system"),
    "upload-area" -> Resource("upload-area", "/api/upload", "files...", "system")
  )

  def handleRequest(rawPath: String, token: TokenService.Token): Either[String, String] = {
    if (!TokenService.verifyToken(token)) {
      return Left("Invalid or expired token")
    }

    if (!PathAuthorizer.checkAccess(rawPath, token.role)) {
      return Left("Access denied")
    }

    // Serve resource based on normalized path
    val normalizedPath = PathAuthorizer.normalizePath(rawPath)
    val matchingResource = resources.values.find(r => normalizedPath.startsWith(r.path))
    matchingResource match {
      case Some(resource) => Right(resource.content)
      case None => Left("Not found")
    }
  }
}
